import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementing tiled matrix multiplication
cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#define TILE 16

__global__ void matmul_tiled(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int row = blockIdx.y * TILE + ty;
    int col = blockIdx.x * TILE + tx;
    float val = 0.0f;

    for (int t = 0; t < (N + TILE - 1) / TILE; ++t) {
        int aIndex = row * N + t * TILE + tx;
        int bIndex = (t * TILE + ty) * N + col;
        As[ty][tx] = (row < N && (t * TILE + tx) < N) ? A[aIndex] : 0.0f;
        Bs[ty][tx] = (col < N && (t * TILE + ty) < N) ? B[bIndex] : 0.0f;
        __syncthreads();

        for (int i = 0; i < TILE; ++i) {
            val += As[ty][i] * Bs[i][tx];
        }
        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = val;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    const int N = A.size(0);
    auto C = torch::zeros_like(A);
    dim3 threads(TILE, TILE);
    dim3 blocks((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);
    matmul_tiled<<<blocks, threads>>>(A.data_ptr<float>(),
                                      B.data_ptr<float>(),
                                      C.data_ptr<float>(),
                                      N);
    return C;
}
"""

# Declaration of the CUDA function
cpp_source = """
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

# Compile and load the custom CUDA operator
matmul_op = load_inline(
    name="matmul_op",
    cpp_sources=[cpp_source],
    cuda_sources=[cuda_source],
    functions=["matmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.matmul = matmul_op

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul.matmul_cuda(A, B)
